using FAQManagement.Authorization; using FAQManagement.Entity; using FAQManagement.Interfaces; using FAQManagement.Model; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; namespace FAQManagement.Controllers { [ApiController][Route("api/[controller]")] public class FAQController:ControllerBase { private readonly IFAQService _faqService; public FAQController(IFAQService faqService){_faqService=faqService;} [HttpGet("GetAll")] public async Task<IActionResult> GetAll()=>Ok(await _faqService.GetAll()); [HttpGet("Paginate")][Authorize][HasPermission("FAQScene.Paging.Permission")] public async Task<IActionResult> Paginate([FromQuery] PagingParameter p)=>Ok(await _faqService.Paginate(p)); [HttpPost("Save")][Authorize][HasPermission("FAQScene.Save.Permission")] public async Task<IActionResult> Save([FromBody] FAQ item)=>Ok(await _faqService.Save(item)); [HttpPost("Update")][Authorize][HasPermission("FAQScene.Edit.Permission")] public async Task<IActionResult> Update([FromBody] FAQ item)=>Ok(await _faqService.Update(item)); [HttpDelete("Delete/{id:long}")][Authorize][HasPermission("FAQScene.Delete.Permission")] public async Task<IActionResult> Delete(long id)=>Ok(await _faqService.Delete(id)); } }